/** 
 * Gets feature specific learning rates Adagrad keeps a history of gradients being passed in. Note that each gradient passed in becomes adapted over time, hence the name adagrad
 * @param gradient the gradient to get learning rates for
 * @param iteration
 * @return the feature specific learning rates
 */
@Override public INDArray getGradient(INDArray gradient,int iteration){
  if (historicalGradient == null)   historicalGradient=gradient.mul(gradient);
 else   historicalGradient.addi(gradient.mul(gradient));
  try {
    INDArray sqrtHistory=sqrt(historicalGradient.add(epsilon));
    INDArray ret=sqrtHistory.rdivi(learningRate).muli(gradient);
    numIterations++;
    return ret;
  } catch (ND4JIllegalStateException | ND4JIllegalArgumentException e) {
    // Handle exception or rethrow
    throw e;
  }
}
